<?php use App\Core\View; ?>
<div class="page-header"><h1>Relatórios</h1></div>
<form class="panel" method="get" action="/reports"><div class="panel-body grid three">
  <div class="field"><label>De</label><input type="date" name="from" value="<?= View::e($from) ?>"></div>
  <div class="field"><label>Até</label><input type="date" name="to" value="<?= View::e($to) ?>"></div>
  <div class="field"><label>&nbsp;</label><button class="primary">Filtrar</button> <a class="button" href="/reports?from=<?= View::e($from) ?>&amp;to=<?= View::e($to) ?>&amp;export=csv">Exportar CSV</a></div>
</div></form>
<div class="panel"><div class="panel-header">Vendas por dia</div><div class="panel-body table-wrap"><table><thead><tr><th>Dia</th><th class="num">Qtd.</th><th class="num">Total</th></tr></thead><tbody><?php foreach ($sales as $r): ?><tr><td><?= View::e($r['day']) ?></td><td class="num"><?= (int) $r['qty'] ?></td><td class="num">R$ <?= number_format((float) $r['total'], 2, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="panel"><div class="panel-header">Produtos mais vendidos</div><div class="panel-body table-wrap"><table><thead><tr><th>Produto</th><th class="num">Qtd.</th><th class="num">Total</th></tr></thead><tbody><?php foreach ($products as $r): ?><tr><td><?= View::e($r['description']) ?></td><td class="num"><?= number_format((float) $r['qty'], 3, ',', '.') ?></td><td class="num">R$ <?= number_format((float) $r['total'], 2, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="panel"><div class="panel-header">Por operador</div><div class="panel-body table-wrap"><table><thead><tr><th>Operador</th><th class="num">Vendas</th><th class="num">Total</th></tr></thead><tbody><?php foreach ($operators as $r): ?><tr><td><?= View::e($r['name']) ?></td><td class="num"><?= (int) $r['qty'] ?></td><td class="num">R$ <?= number_format((float) $r['total'], 2, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="panel"><div class="panel-header">Por forma de pagamento</div><div class="panel-body table-wrap"><table><thead><tr><th>Forma</th><th class="num">Total</th></tr></thead><tbody><?php foreach ($payments as $r): ?><tr><td><?= View::e($r['name']) ?></td><td class="num">R$ <?= number_format((float) $r['total'], 2, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="panel"><div class="panel-header">Estoque baixo</div><div class="panel-body table-wrap"><table><thead><tr><th>Produto</th><th class="num">Saldo</th><th class="num">Mínimo</th></tr></thead><tbody><?php foreach ($lowStock as $r): ?><tr><td><?= View::e($r['description']) ?></td><td class="num"><?= number_format((float) $r['stock'], 3, ',', '.') ?></td><td class="num"><?= number_format((float) $r['minimum_stock'], 3, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="panel"><div class="panel-header">Devoluções</div><div class="panel-body table-wrap"><table><thead><tr><th>Devolução</th><th>Venda</th><th>Data</th><th class="num">Total</th></tr></thead><tbody><?php foreach ($returns as $r): ?><tr><td><?= View::e($r['return_number']) ?></td><td><?= View::e($r['sale_number']) ?></td><td><?= View::e($r['created_at']) ?></td><td class="num">R$ <?= number_format((float) $r['total'], 2, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<div class="panel"><div class="panel-header">Fechamentos de caixa</div><div class="panel-body table-wrap"><table><thead><tr><th>Caixa</th><th>Operador</th><th>Abertura</th><th class="num">Esperado</th><th class="num">Contado</th><th class="num">Diferença</th></tr></thead><tbody><?php foreach ($cash as $r): ?><tr><td><?= View::e($r['register_name']) ?></td><td><?= View::e($r['operator_name']) ?></td><td><?= View::e($r['opened_at']) ?></td><td class="num"><?= $r['expected_cash'] === null ? '—' : 'R$ ' . number_format((float) $r['expected_cash'], 2, ',', '.') ?></td><td class="num"><?= $r['counted_cash'] === null ? '—' : 'R$ ' . number_format((float) $r['counted_cash'], 2, ',', '.') ?></td><td class="num"><?= $r['difference_amount'] === null ? '—' : 'R$ ' . number_format((float) $r['difference_amount'], 2, ',', '.') ?></td></tr><?php endforeach ?></tbody></table></div></div>
<p class="muted">Todos os valores vêm dos registros reais do banco. Não há emissão fiscal nestes relatórios.</p>
